        counts = {}
        keys = []
        for sub in candidates:
            key = tuple(tuple(row) for row in sub)
            keys.append(key)
            counts[key] = counts.get(key, 0) + 1
        best_key = min(counts, key=lambda k: counts[k])
        for sub, key in zip(candidates, keys):
            if key == best_key:
                return sub

